INSERT OR REPLACE INTO settings(key,value) VALUES ('faq','[{"id":"faq-1","question":"Can I request a custom design?","answer":"Yes. Send a photo, sketch, STL file, product link or just describe the idea on WhatsApp. We''ll confirm size, material, colour and price before printing anything.","active":true},{"id":"faq-2","question":"What can I send as a reference for custom printing?","answer":"Any of these works: a photo, a hand sketch, an STL/OBJ model, a product link or a rough description with dimensions. More detail means a faster, more accurate quote.","active":true},{"id":"faq-3","question":"Do you print prototypes and functional parts?","answer":"Yes. We print prototypes, brackets, holders, replacement parts and other functional pieces. Tell us what the part does so we can suggest the right material and strength.","active":true},{"id":"faq-4","question":"How do I place an order?","answer":"Open any product, choose quantity and colour, and tap Enquire on WhatsApp. Your selection is filled into the message. We confirm price and delivery, then start printing after you approve.","active":true},{"id":"faq-5","question":"Can I choose the colour?","answer":"For most products, yes. Available colours vary by design and material, so ask on WhatsApp before ordering and we''ll confirm what''s in stock.","active":true},{"id":"faq-6","question":"What materials do you print with?","answer":"Mostly PLA and PETG, which suit décor, gifts and everyday functional use. If you need a specific material or finish, mention it in your enquiry.","active":true},{"id":"faq-7","question":"How long does an order take?","answer":"Ready designs usually take a few days. Custom or large pieces take longer. We give you a clear timeline when we confirm the order.","active":true},{"id":"faq-8","question":"Do you deliver outside Delhi & NCR?","answer":"We focus on Delhi & NCR. For other cities, message us with your pincode and we''ll tell you if delivery is possible and what it costs.","active":true},{"id":"faq-9","question":"How much does shipping cost?","answer":"Delivery charges depend on your location, the size of the piece and the number of items. We share the exact amount before you confirm the order.","active":true},{"id":"faq-10","question":"Can I order in bulk or for gifting?","answer":"Yes. We take corporate gifting, return gifts and event orders. Share the quantity and date, and we''ll quote a per-piece price.","active":true},{"id":"faq-11","question":"Can you change the size of an existing product?","answer":"Often, yes. Many designs can be scaled up or down. Ask for the size you need and we''ll confirm if it prints well at that size.","active":true},{"id":"faq-12","question":"How do I pay?","answer":"We confirm payment details on WhatsApp once the order is agreed. UPI and bank transfer are the usual options.","active":true},{"id":"faq-13","question":"What if my piece arrives damaged?","answer":"Message us on WhatsApp with photos within 48 hours of delivery. We''ll look at it and arrange a repair, reprint or refund as per our returns policy.","active":true},{"id":"faq-14","question":"Can I return a custom-made piece?","answer":"Custom pieces are made only for you, so they can''t be returned unless they arrive damaged or different from what we agreed. Check the returns page for details.","active":true},{"id":"faq-15","question":"How do I care for 3D printed décor?","answer":"Keep it away from direct heat and long sun exposure. Wipe with a dry or slightly damp soft cloth. Avoid harsh cleaners.","active":true},{"id":"faq-16","question":"Can I leave a review?","answer":"Yes. Open the product you bought and use the review form at the bottom. Reviews are checked by our team before they appear on the site.","active":true}]');
INSERT OR REPLACE INTO settings(key,value) VALUES ('site','{"version":1,"siteName":"Mokova3D","tagline":"Custom 3D printing, creative décor, gifts and more.","whatsapp":"918527373680","instagram":"https://instagram.com/mokova3d","heroEyebrow":"Mokova3D · Custom 3D Printing","heroTitle":"Turning ideas into reality.","heroDescription":"From cute desk companions to statement décor, prototypes and functional parts — we turn digital ideas into physical objects with 3D printing.","heroPrimary":"Explore Products →","heroSecondary":"Start a Project","deliveryArea":"Delhi & NCR","currency":"INR","metaTitle":"3D Printing in Delhi | Custom 3D Prints & Décor | Mokova3D","metaDescription":"Mokova3D offers custom 3D printing in Delhi for home décor, gifts, prototypes, functional parts and creative designs.","announcement":"Custom orders available — send your idea on WhatsApp.","showAnnouncement":true,"banners":[{"id":"hero-1","active":true,"title":"Made for people who like different.","subtitle":"3D printed décor, gifts, collectibles and custom creations.","button":"Shop Products","link":"products.html","image":"assets/hero.jpg","badge":"MOKOVA3D"},{"id":"hero-2","active":true,"title":"Have an idea? We can print it.","subtitle":"Send a photo, sketch, STL or reference and get a custom quote on WhatsApp.","button":"Start Custom Order","link":"contact.html","image":"assets/products/figurine.jpg","badge":"CUSTOM 3D PRINTING"},{"id":"hero-3","active":true,"title":"Gifts, décor & fun prints.","subtitle":"Discover small-batch designs made for desks, shelves, gifting and everyday use.","button":"Explore Collection","link":"products.html","image":"assets/products/penguin.jpg","badge":"READY TO ENQUIRE"}],"content":{"nav":{"home":{"label":"Home","href":"index.html","show":true},"shop":{"label":"Shop","href":"products.html","show":true},"categories":{"label":"Categories ▾","show":true},"gallery":{"label":"Gallery","href":"gallery.html","show":true},"about":{"label":"About","href":"about.htm