tle":"Instagram","text":"@mokova3d","link":"https://instagram.com/mokova3d"},{"title":"Location","text":"Delhi & NCR","link":"#"},{"title":"Send us","text":"Photo, sketch, STL or link","link":"#"}],"formTitle":"Send an enquiry","formText":"Tell us what you want to buy or customise. The form opens WhatsApp with the details filled in.","side":[{"title":"What you can send","text":"Product name, reference photo, sketch, STL/model details, quantity, preferred colour, size and delivery location."},{"title":"Quick contact","text":"WhatsApp: +91 85273 73680 · Instagram: @mokova3d"}]},"product":{"points":[{"title":"Customisation","text":"Ask about colour, size and quantity."},{"title":"Delivery","text":"Share your pincode for delivery guidance."},{"title":"Ordering","text":"Direct WhatsApp enquiry — no complicated checkout."}],"reviewsKicker":"Customer reviews","reviewsTitle":"What customers say.","reviewsLead":"Reviews from customers who bought this product.","reviewFormTitle":"Leave a review","check":{"show":true,"kicker":"Before ordering","title":"Need a custom version?","lead":"Send a reference image, size requirement or colour preference. We''ll confirm feasibility, final price and delivery before you place the order.","items":[{"title":"Size","text":"Tell us the approximate height, width or dimensions you need."},{"title":"Colour","text":"Ask about available colours or share your preferred look."},{"title":"Quantity","text":"Single pieces and multiple-piece enquiries can be discussed."},{"title":"Reference","text":"Send a photo, sketch, link or model after WhatsApp opens."}]},"feedback":{"show":true,"kicker":"Customer feedback","title":"Real orders. Real feedback.","lead":"We don''t publish made-up ratings. If you''ve ordered from Mokova, you can share your experience on our Google Business Profile.","boxTitle":"Have you bought from Mokova?","boxText":"Tell future customers about the product, finish, communication and delivery experience.","button":"Leave a Google review ↗","link":"https://share.google/YX2edKcaZqEUT6W5S"},"faq":{"show":true,"kicker":"FAQ","title":"Product questions, answered.","items":[{"question":"Is the displayed price final?","answer":"Only prices explicitly shown on the product listing are displayed. Customisation, quantity and delivery can change the final quote, so confirm on WhatsApp."},{"question":"Can I request another colour?","answer":"For many products, yes. Availability depends on the current material/colour stock."},{"question":"Can I order more than one?","answer":"Yes. Enter the quantity and send the enquiry; bulk or multiple-piece requirements can be discussed."},{"question":"Can I send a reference image?","answer":"Yes. After WhatsApp opens, attach the reference image, sketch or screenshot in the chat."}]}},"cta":{"show":true,"kicker":"Need help?","title":"Talk to Mokova directly.","text":"Questions about an order, a design or delivery? We reply on WhatsApp.","button":"Chat on WhatsApp","link":"https://wa.me/918527373680"},"footer":{"about":"3D printed gifts, décor, collectibles and custom creations.","shopTitle":"Shop","shopLabel":"All products","shopLink":"products.html","helpTitle":"Help","help":[{"label":"Custom order","link":"contact.html"},{"label":"FAQ","link":"faq.html"},{"label":"Delivery","link":"shipping.html"},{"label":"Returns","link":"returns.html"}],"connectTitle":"Connect","connect":[{"label":"Chat with Mokova","link":"https://wa.me/918527373680"},{"label":"Instagram · @mokova3d","link":"https://instagram.com/mokova3d"}],"policy":[{"label":"Privacy","link":"privacy.html"},{"label":"Terms","link":"terms.html"},{"label":"Returns","link":"returns.html"}],"copyLeft":"© 2026 Mokova3D","copyRight":"Delhi & NCR · Ideas. Designed. Printed."}}}');
INSERT OR REPLACE INTO blog_posts(id,slug,title,data,status,published_at) VALUES ('blog-1','3d-printing-ideas','What can you make with 3D printing?','{"id":"blog-1","slug":"3d-printing-ideas","title":"What can you make with 3D printing?","excerpt":"Practical, decorative and personalised possibilities for 3D printing.","content":"<p>3D printing can turn a digital idea into a physical object. At Mokova3D, we use it for décor, gifts, prototypes, functional parts and custom designs.</p><h2>Start with an idea</h2><p>A reference photo, sketch, STL file or even a rough description can be enough to begin a conversation.</p>","featured_image":"assets/hero.jpg","status":"published"}', 'published', CURRENT_TIMESTAMP);
INSERT OR REPLACE INTO blog_posts(id,slug,title,data,status,published_at) VALUES ('blog-2','3d-printed-gifts','Why 3D printed décor makes a thoughtful gift','{"id":"blog-2","slug":"3d-printed-gifts","title":"Why 3D printed décor makes a thoughtful gift","excerpt":"Small, personal and easy to customise.","content":"<p>A 3D printed gift can be playful, useful or deeply personal. You can choose a shape, colour, size or theme that fits the person receiving it.</p>","featured_image":"assets/products/cat.jpg","status":"published"}', 'published', CURRENT_TIMESTAMP);
COMMIT;
